#root#root .shell .mc-gs-chips button.is-active b { color: var(--mc-accent); }
#root#root .shell .mc-gs-chips .chip-failed.is-active b { color: var(--mc-danger); }
#root#root .shell .mc-gs-chips .chip-review.is-active b { color: var(--mc-warning); }

