  display: flex;
  flex-direction: column;
  gap: 0;
  overflow: hidden;
  background: rgba(8, 12, 17, 0.45) !important;
  border: 1px solid var(--mc-border) !important;
  border-radius: 9px !important;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.02) !important;
}
#root#root .shell .mc-ref-manifest-row {
  position: relative;
  display: grid !important;
  grid-template-columns: 3px 22px minmax(0, 1.8fr) minmax(0, 104px) 84px minmax(0, 1.25fr) 92px auto !important;
  align-items: center !important;
  gap: 12px !important;
  min-height: var(--mc-manifest-row-height, 48px) !important;
  padding: 10px 14px !important;
  content-visibility: visible !important;
  background: transparent !important;
  border: 0 !important;
  border-bottom: 1px solid rgba(195, 211, 228, 0.06) !important;
  border-radius: 0 !important;
  cursor: pointer;
  transition: background-color 120ms ease-out;
}
#root#root .shell .mc-ref-manifest-row:last-child { border-bottom: 0 !important; }
#root#root .shell .mc-ref-manifest-row:hover { background: rgba(255, 255, 255, 0.03) !important; }
#root#root .shell .mc-ref-manifest-row.is-selected {
  background: rgba(169, 221, 196, 0.08) !important;
  box-shadow: inset 0 0 0 1px rgba(169, 221, 196, 0.22);
}

#root#root .shell .mc-ref-manifest-row .mc-ref-state-bar {
  align-self: center;
  width: 3px; height: 22px;
  border-radius: var(--mc-radius-pill);
  background: var(--mc-text-dim);
  opacity: .5;
}
#root#root .shell .mc-ref-manifest-row.state-ok .mc-ref-state-bar { background: var(--mc-accent); opacity: 1; box-shadow: 0 0 10px -2px var(--mc-accent); }
#root#root .shell .mc-ref-manifest-row.state-warn .mc-ref-state-bar { background: var(--mc-warning); opacity: 1; box-shadow: 0 0 10px -2px var(--mc-warning); }
#root#root .shell .mc-ref-manifest-row.state-crit .mc-ref-state-bar { background: var(--mc-danger); opacity: 1; box-shadow: 0 0 10px -2px var(--mc-danger); }

#root#root .shell .mc-gs-star {
  display: grid; place-items: center;
  width: 22px; height: 22px;
  color: var(--mc-text-dim); background: transparent;
  border: 0; border-radius: var(--mc-radius-xs);
  opacity: .45;
  cursor: pointer;
}
#root#root .shell .mc-ref-manifest-row:hover .mc-gs-star,
#root#root .shell .mc-ref-manifest-row.is-selected .mc-gs-star { opacity: 1; }
#root#root .shell .mc-gs-star:hover { color: var(--mc-text-soft); background: color-mix(in srgb, var(--mc-text) 8%, transparent); }
#root#root .shell .mc-gs-star.is-on { color: var(--mc-warning); opacity: 1; }
#root#root .shell .mc-gs-star.is-on .icon { fill: currentColor; }

#root#root .shell .mc-ref-manifest-row .mc-ref-worker-name { min-width: 0; }
#root#root .shell .mc-gs-name-line { display: flex; align-items: center; gap: 7px; min-width: 0; }
#root#root .shell .mc-gs-name-line strong {
  overflow: hidden;
  font-size: 12.5px; font-weight: 550; letter-spacing: -.012em;
  text-overflow: ellipsis; white-space: nowrap;
}
#root#root .shell .mc-gs-evidence {
  flex: 0 0 auto;
  padding: 1px 7px;
  color: var(--mc-text-muted);
  background: color-mix(in srgb, var(--mc-void) 45%, transparent);
  border: 1px solid var(--mc-border);
  border-radius: var(--mc-radius-pill);
  font-family: var(--mc-font-mono, ui-monospace, "SF Mono", Menlo, monospace);
  font-size: 9.5px; font-weight: 600; letter-spacing: .01em;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
#root#root .shell .mc-gs-evidence.tone-ok { color: var(--mc-ok); border-color: color-mix(in srgb, var(--mc-ok) 26%, transparent); background: var(--mc-ok-soft); }
#root#root .shell .mc-gs-evidence.tone-warn { color: var(--mc-warning); border-color: color-mix(in srgb, var(--mc-warning) 28%, transparent); background: var(--mc-warning-soft); }
#root#root .shell .mc-gs-evidence.tone-crit { color: var(--mc-danger); border-color: color-mix(in srgb, var(--mc-danger) 30%, transparent); background: var(--mc-danger-soft); }
#root#root .shell .mc-ref-manifest-row .mc-ref-worker-name code {
  display: block; overflow: hidden;
  margin-top: 2px;
  color: var(--mc-text-dim); font-size: 10.5px; letter-spacing: -.005em;
  text-overflow: ellipsis; white-space: nowrap;
}
#root#root .shell .mc-ref-manifest-row .mc-ref-role,
#root#root .shell .mc-ref-manifest-row .mc-gs-activity,
#root#root .shell .mc-ref-manifest-row .mc-ref-resource {
  overflow: hidden;
  color: var(--mc-text-muted); font-size: 11px;
  text-overflow: ellipsis; white-space: nowrap;
}
#root#root .shell .mc-ref-manifest-row .mc-ref-role { font-size: 10.5px; letter-spacing: .01em; }
#root#root .shell .mc-ref-manifest-row .mc-ref-resource { text-align: right; font-variant-numeric: tabular-nums; color: var(--mc-text-dim); }
#root#root .shell .mc-ref-manifest-row .mc-ref-status {
  display: inline-flex;
  align-items: center !important;
  gap: 6px !important;
  padding: 3px 8px !important;
  border-radius: 5px !important;
  font-size: 11px !important;
  font-weight: 500 !important;
  letter-spacing: .01em !important;
  white-space: nowrap !important;
  backdrop-filter: blur(8px) !important;
  -webkit-backdrop-filter: blur(8px) !important;
}

@keyframes mc-worker-beacon-pulse {
  0%, 100% {
    box-shadow: 0 0 0 2px color-mix(in srgb, var(--mc-ok) 25%, transparent), 0 0 8px currentColor;
    transform: scale(1);
  }
  50% {
    box-shadow: 0 0 0 4px color-mix(in srgb, var(--mc-ok) 45%, transparent), 0 0 14px currentColor;
    transform: scale(1.15);
  }
}
#root#root .shell .mc-ref-manifest-row .mc-ref-status.tone-running {
  color: var(--mc-ok) !important;
  background: rgba(169, 221, 196, 0.08) !important;
  border: 1px solid rgba(169, 221, 196, 0.18) !important;
  box-shadow: 0 0 8px rgba(169, 221, 196, 0.12) !important;
}
#root#root .shell .mc-ref-manifest-row .mc-ref-status.tone-running > i {
  animation: mc-worker-beacon-pulse 2.2s ease-in-out infinite;
}
#root#root .shell .mc-ref-manifest-row .mc-ref-status.tone-warning {
  color: var(--mc-warning) !important;
  background: rgba(237, 197, 139, 0.08) !important;
  border: 1px solid rgba(237, 197, 139, 0.18) !important;
  box-shadow: 0 0 8px rgba(237, 197, 139, 0.12) !important;
}
#root#root .shell .mc-ref-manifest-row .mc-ref-status.tone-critical {
  color: var(--mc-danger) !important;
  background: rgba(242, 167, 174, 0.08) !important;
  border: 1px solid rgba(242, 167, 174, 0.18) !important;
  box-shadow: 0 0 8px rgba(242, 167, 174, 0.12) !important;
}
#root#root .shell .mc-ref-manifest-row .mc-ref-status > i {
  background: currentColor !important;
  border-color: currentColor !important;
  box-shadow: 0 0 6px currentColor !important;
}
#root#root .shell .mc-ref-manifest-row .mc-ref-status.tone-idle {
  color: var(--mc-text-dim) !important;
  background: rgba(255, 255, 255, 0.03) !important;
  border: 1px solid var(--mc-border) !important;
  box-shadow: none !important;
}
#root#root .shell .mc-ref-manifest-row .mc-ref-status.tone-idle > i { box-shadow: none !important; }

#root#root .shell .mc-ref-manifest-row .mc-gs-row-action {
  min-height: 27px; padding: 0 12px;
  color: var(--mc-text-muted); background: transparent;
  border: 1px solid var(--mc-border); border-radius: var(--mc-radius-sm);
  font-size: 11px; font-weight: 500; white-space: nowrap; cursor: pointer;
}
#root#root .shell .mc-ref-manifest-row:hover .mc-gs-row-action,
#root#root .shell .mc-ref-manifest-row.is-selected .mc-gs-row-action,
#root#root .shell .mc-ref-manifest-row .mc-gs-row-action:focus-visible {
  color: var(--mc-text);
  background: var(--mc-surface-2);
  border-color: var(--mc-border-strong);
  box-shadow: var(--mc-raise-1);
}
#root#root .shell .mc-ref-manifest-row .mc-gs-row-action:hover { color: var(--mc-text); border-color: var(--mc-border-strong); }
#root#root .shell .mc-ref-manifest-row.state-crit .mc-gs-row-action { color: color-mix(in srgb, var(--mc-danger) 80%, var(--mc-text-muted)); border-color: color-mix(in srgb, var(--mc-danger) 26%, transparent); }
#root#root .shell .mc-ref-manifest-row.state-crit:hover .mc-gs-row-action { color: var(--mc-danger); border-color: color-mix(in srgb, var(--mc-danger) 42%, transparent); }

#root#root .shell .mc-ref-empty {
  display: flex; flex-direction: column; align-items: center; gap: 7px;
  padding: 34px 20px;
  background: var(--mc-surface);
  border: 1px dashed var(--mc-border);
  border-radius: var(--mc-radius-md);
  text-align: center;
}
#root#root .shell .mc-ref-empty strong { font-size: 13.5px; font-weight: 600; letter-spacing: -.012em; }
#root#root .shell .mc-ref-empty span { color: var(--mc-text-muted); font-size: 12px; }
#root#root .shell .mc-ref-empty button {
  margin-top: 5px; min-height: 30px; padding: 0 14px;
  color: var(--mc-text); background: var(--mc-surface-2);
  border: 1px solid var(--mc-border); border-radius: var(--mc-radius-sm);
  box-shadow: var(--mc-raise-1);
  font-size: 12px; cursor: pointer;
}

/* --------------------------------------------------------- lower panels */

#root#root .shell .mc-ref-lower-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(276px, 1fr)); gap: 14px; align-items: start; }
#root#root .shell .mc-ref-lower-grid .mc-ref-panel {
  display: flex; flex-direction: column; gap: 11px;
  min-width: 0;
  padding: 18px 20px;
