#root#root .shell .mc-ref-lower-grid .mc-ref-panel > header { display: flex; align-items: center; justify-content: space-between; gap: 10px; }
#root#root .shell .mc-ref-lower-grid .mc-ref-panel h3 { color: var(--mc-text-dim); font-size: 10px; font-weight: 600; letter-spacing: .08em; text-transform: uppercase; }
#root#root .shell .mc-ref-lower-grid .mc-ref-panel > header button {
  padding: 4px 9px;
  color: var(--mc-text-muted); background: transparent;
  border: 1px solid var(--mc-border); border-radius: var(--mc-radius-xs);
  font-size: 11px; cursor: pointer;
}

